const TOOL_VALUES = { user: "the user's name", char: "the character's name", character_name: "the character's name", "<tool>": "a tool's own name, such as {{read}}, while that tool is on" };

export function toolText(tool: string): string {
  return `tool_${tool}`;
}

export function parameterText(tool: string, parameter: string): string {
  return `tool_${tool}_${parameter}`;
}

export const TOOL_TEXTS: readonly TextSpec[] = Object.entries(TOOL_TEXTS_SHIPPED).flatMap(([tool, { description, parameters }]) => [
  text(toolText(tool), description, `The description of the ${tool} tool.`, TOOL_VALUES),
  ...Object.entries(parameters).map(([parameter, shipped]) => text(parameterText(tool, parameter), shipped, `The description of the ${parameter} parameter of ${tool}.`, TOOL_VALUES)),
]);

export const TEXTS: readonly TextSpec[] = [...MESSAGE_TEXTS, ...SYSTEM_TEXTS, ...WAKE_TEXTS, ...TOOL_TEXTS, ...OTHER_TEXTS, ...IMAGE_TEXTS, ...READ_TEXTS, ...MCP_TEXTS, ...SEND_TEXTS, ...ARG_TEXTS, ...WAKE_TOOL_TEXTS, ...TOOL_COMMON_TEXTS, ...ARG_COMMON_TEXTS, ...THREADS_TOOL_TEXTS, ...TRIGGERS_TOOL_TEXTS, ...FILE_TEXTS, ...EDIT_TEXTS, ...PICTURE_SEND_TEXTS, ...GUIDE_TEXTS];

export const TEXT_SPECS: ReadonlyMap<string, TextSpec> = new Map(TEXTS.map((spec) => [spec.name, spec]));

export function shippedText(name: string): string {
  const spec = TEXT_SPECS.get(name);
  if (spec === undefined) throw new Error(`Shore has no text named "${name}"`);
  return spec.shipped;
}
